import{_ as a,o,c as s,a1 as i}from"./chunks/framework.DceXOx8u.js";const u=JSON.parse('{"title":"Actualizar a estable: cambios de comportamiento","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://andresayac.github.io/botmesh/es/guide/migracion-2"}],["meta",{"property":"og:url","content":"https://andresayac.github.io/botmesh/es/guide/migracion-2"}]]},"headers":[],"relativePath":"es/guide/migracion-2.md","filePath":"es/guide/migracion-2.md"}'),t={name:"es/guide/migracion-2.md"};function n(d,e,r,c,l,p){return o(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="actualizar-a-estable-cambios-de-comportamiento" tabindex="-1">Actualizar a estable: cambios de comportamiento <a class="header-anchor" href="#actualizar-a-estable-cambios-de-comportamiento" aria-label="Permalink to &quot;Actualizar a estable: cambios de comportamiento&quot;">​</a></h1><p>Paso 5 del <a href="./migracion-estable#checklist-de-actualizacion">checklist de actualización</a>. <code>@botmesh/core</code> 2.0 sale de la serie alpha con unos pocos cambios de comportamiento deliberados. Esta página explica cada uno, qué cambió y cómo mantener el comportamiento anterior cuando todavía es posible. La mayoría de los bots necesitan como mucho dos cambios: <code>lang: &#39;es&#39;</code> si el bot habla español y <code>maxAttempts</code> donde una espera usaba <code>retries</code>.</p><table tabindex="0"><thead><tr><th>Cambio</th><th>A quién afecta</th><th>Qué hacer</th></tr></thead><tbody><tr><td><a href="#los-textos-internos-pasan-a-ingles">Los textos internos pasan a inglés</a></td><td>Bots que contaban con los textos en español</td><td>Añade <code>lang: &#39;es&#39;</code></td></tr><tr><td><a href="#retries-y-maxattempts"><code>retries</code> y <code>maxAttempts</code></a></td><td>Esperas, formularios y flujos JSON con <code>retries</code></td><td>Cambia <code>retries: N</code> por <code>maxAttempts: N</code></td></tr><tr><td><a href="#los-envios-necesitan-el-bot-en-marcha">Los envíos necesitan el bot en marcha</a></td><td>Código que envía antes de <code>start()</code> o después de <code>stop()</code></td><td>Envía después de <code>start()</code> o captura <code>BotNotRunningError</code></td></tr><tr><td><a href="#los-flujos-se-validan-al-definirlos">Los flujos se validan al definirlos</a></td><td><code>choose({})</code>, <code>ask(texto, &#39;&#39;)</code></td><td>Corrige la definición</td></tr><tr><td><a href="#un-envio-de-ctx-limitado-se-reintenta-una-vez">Un envío de <code>ctx</code> limitado se reintenta una vez</a></td><td>Bots sobre transportes que responden 429</td><td>Nada, o ajusta <code>rateLimitRetry</code></td></tr><tr><td><a href="#eventos-de-provider-invalidos">Eventos de provider inválidos</a></td><td>Providers propios</td><td>Emite eventos bien formados</td></tr><tr><td><a href="#un-hook-que-llama-a-next-dos-veces">Un hook que llama a <code>next()</code> dos veces</a></td><td>Hooks con ese error</td><td>Llama a <code>next()</code> una sola vez</td></tr><tr><td><a href="#los-ids-de-los-logs-van-hasheados">Los ids de los logs van hasheados</a></td><td>Búsquedas en logs por teléfono o id de chat</td><td><code>logIds: &#39;raw&#39;</code> para depurar en local</td></tr><tr><td><a href="#logs-append-danados">Logs append dañados</a></td><td><code>FileDurability</code> / <code>SharedFileEventJournal</code> con <code>appendLog</code></td><td>Repara el log si <code>open</code> lo rechaza</td></tr><tr><td><a href="#memorycoordinationhub-expulsa-chats-inactivos"><code>MemoryCoordinationHub</code> expulsa chats inactivos</a></td><td>Tests que inspeccionan el hub</td><td>Nada</td></tr><tr><td><a href="#reintentos-de-broadcast"><code>broadcast({ maxRetries })</code></a></td><td>Difusiones</td><td>Renómbralo a <code>retries</code> (el alias se mantiene)</td></tr><tr><td><a href="#las-etiquetas-de-whatsapp-flows-pasan-a-ingles">Las etiquetas de WhatsApp Flows pasan a inglés</a></td><td>Formularios de <code>@botmesh/meta</code> publicados con <code>toFlowJson</code> / <code>publishForm</code></td><td>Pasa <code>lang: &#39;es&#39;</code></td></tr><tr><td><a href="#presencia-sin-conexion">Presencia sin conexión</a></td><td>Código que esperaba que <code>typing()</code> / <code>markRead()</code> lanzaran sin conexión; providers propios</td><td>Nada; los providers propios resuelven sin conexión</td></tr><tr><td><a href="#evento-stopping">Evento <code>&#39;stopping&#39;</code></a></td><td>Plugins que cancelan trabajo en <code>&#39;stopped&#39;</code></td><td>Escucha <code>&#39;stopping&#39;</code> para cancelar antes de parar el transporte</td></tr><tr><td><a href="#los-flujos-persistentes-hacen-checkpoint-al-empezar">Los flujos persistentes hacen checkpoint al empezar</a></td><td>Stores que cuentan escrituras de checkpoint</td><td>Nada (una escritura más por entrada al flujo)</td></tr><tr><td><a href="#mensajes-de-error-sin-ids-de-chat">Mensajes de error sin ids de chat</a></td><td>Código que sacaba el chat del mensaje de un error</td><td>Lee <code>error.chatId</code></td></tr><tr><td><a href="#arreglos-menores">Arreglos menores</a></td><td><code>ctx.delete()</code> después de <code>stop()</code>, <code>ctx.acknowledge</code>, tipos de evento desconocidos, <code>lang</code> + <code>i18n.defaultLocale</code>, <code>ChaosProvider.selfId</code></td><td>Ver la sección</td></tr></tbody></table><h2 id="los-textos-internos-pasan-a-ingles" tabindex="-1">Los textos internos pasan a inglés <a class="header-anchor" href="#los-textos-internos-pasan-a-ingles" aria-label="Permalink to &quot;Los textos internos pasan a inglés&quot;">​</a></h2><p>Los textos que el core escribe por ti (expiración de la conversación, &quot;demasiados intentos&quot;, avisos de las esperas, respuestas de los comandos slash, pistas de los formularios y la palabra para omitir un campo) estaban en español salvo que el bot configurara i18n. Ahora están en inglés: la palabra para omitir es <code>skip</code>, el mensaje de reintentos es <code>❌ Too many attempts. Conversation ended.</code>, etc. <code>@botmesh/ai</code> hace lo mismo: sus textos internos (pregunta de confirmación, botones Sí/No, respuestas de reserva, línea de fuentes) están en inglés cuando no se conoce el idioma.</p><p>Los textos en español siguen incluidos. Una opción los recupera sin activar la resolución de idioma por usuario:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> bot</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Bot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ provider, lang: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;es&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span></code></pre></div><p><code>i18n: { defaultLocale: &#39;es&#39; }</code> también sirve, pero activa la resolución de idioma (preferencia guardada, idioma del cliente, detector). Consulta <a href="./i18n#un-bot-en-un-solo-idioma-lang">Internacionalización</a>. Las plantillas de <code>create-botmesh</code> ya ponen <code>lang: &#39;es&#39;</code>.</p><h2 id="retries-y-maxattempts" tabindex="-1"><code>retries</code> y <code>maxAttempts</code> <a class="header-anchor" href="#retries-y-maxattempts" aria-label="Permalink to &quot;`retries` y `maxAttempts`&quot;">​</a></h2><p>Toda opción <code>retries</code> significa ahora lo mismo: intentos <strong>después</strong> del primero. Así funcionaba ya <code>durability.outbox.retries</code>, pero en las esperas (<code>ask</code>, <code>waitText</code>, <code>choose</code>…), los pasos de formulario y los pasos <code>ask</code>/<code>form</code> de los flujos JSON <code>retries: N</code> significaba N respuestas en total. El total tiene ahora su propia opción:</p><ul><li><code>maxAttempts: N</code>: la espera acepta N respuestas en total, la primera incluida.</li><li><code>retries: N</code>: equivale a <code>maxAttempts: N + 1</code>.</li></ul><p>El valor por defecto no cambia (3 respuestas en total). Para conservar el comportamiento de las alphas, cambia el nombre de la opción:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 2.0 alpha: 3 respuestas en total</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flow</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;x&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ask</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;¿Email?&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;email&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { validate, retries: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 2.0: lo mismo</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flow</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;x&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ask</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;¿Email?&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;email&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { validate, maxAttempts: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span></code></pre></div><p>Pasar las dos con valores que no cuadran lanza un <code>TypeError</code>. Los valores inválidos (<code>maxAttempts: 0</code>, <code>retries: -1</code>) lanzan al definir el flujo. <code>bot.broadcast()</code> sigue la misma convención (ver <a href="#reintentos-de-broadcast">más abajo</a>).</p><p>El código que aún no hayas renombrado sigue funcionando con una respuesta más que antes. Para que se note, el bot escribe <strong>un aviso</strong> (<code>logger.warn</code>, una vez por bot) la primera vez que una espera, un formulario o un paso de flujo usa <code>retries</code> sin <code>maxAttempts</code>. Poner <code>maxAttempts</code> (sola o con un <code>retries</code> que cuadre) lo silencia.</p><p>Los documentos de flujo JSON (<code>@botmesh/flow-schema</code>, que guardan el manager y <code>@botmesh/deployments</code>) no cambian de significado: el formato pasa a la <strong>versión 2</strong> y un documento de la versión 1 se migra al cargarlo (<code>validateFlowDocument</code>, <code>compileFlowDocument</code>, <code>flowFromArtifact</code> o, de forma explícita, <code>migrateFlowDocument</code>). La migración 1 → 2 reescribe <code>retries: N</code> como <code>maxAttempts: N</code> (un <code>retries: 0</code> antiguo se comportaba como 1 y pasa a <code>maxAttempts: 1</code>), así que los flujos v1 publicados conservan su presupuesto. En un documento de la versión 2, <code>retries</code> tiene el significado nuevo. <code>isFlowDocument()</code> solo acepta la versión actual.</p><h2 id="los-envios-necesitan-el-bot-en-marcha" tabindex="-1">Los envíos necesitan el bot en marcha <a class="header-anchor" href="#los-envios-necesitan-el-bot-en-marcha" aria-label="Permalink to &quot;Los envíos necesitan el bot en marcha&quot;">​</a></h2><p><code>bot.send()</code>, <code>ctx.reply()</code>, las ediciones y las actualizaciones de stream hechas antes de <code>bot.start()</code> (o tras un arranque fallido) o después de <code>bot.stop()</code> llegaban al provider. Ahora rechazan con <code>BotNotRunningError</code> (<code>code: &#39;BOT_NOT_RUNNING&#39;</code>) y no envían nada. Los envíos se aceptan desde que el transporte empieza a conectar, así que un listener de <code>&#39;ready&#39;</code> puede seguir enviando.</p><p>Las llamadas concurrentes a <code>start()</code> / <code>stop()</code> se ejecutan de una en una y en orden: la última decide el estado final (<code>start(); stop(); start()</code> termina en marcha).</p><h2 id="los-flujos-se-validan-al-definirlos" tabindex="-1">Los flujos se validan al definirlos <a class="header-anchor" href="#los-flujos-se-validan-al-definirlos" aria-label="Permalink to &quot;Los flujos se validan al definirlos&quot;">​</a></h2><p>Estos casos solo fallaban cuando un usuario llegaba al paso. Ahora lanzan un <code>TypeError</code> al definir el flujo:</p><ul><li><code>.choose(prompt, {})</code> (sin opciones), <code>options</code> que no es un objeto, o una opción sin etiqueta;</li><li><code>.ask(texto, &#39;&#39;)</code> o <code>.choose(prompt, opciones, &#39;&#39;)</code> (clave de estado vacía);</li><li><code>maxAttempts</code> / <code>retries</code> inválidos en <code>.ask()</code>, <code>.choose()</code> y <code>.form()</code>.</li></ul><h2 id="un-envio-de-ctx-limitado-se-reintenta-una-vez" tabindex="-1">Un envío de <code>ctx</code> limitado se reintenta una vez <a class="header-anchor" href="#un-envio-de-ctx-limitado-se-reintenta-una-vez" aria-label="Permalink to &quot;Un envío de `ctx` limitado se reintenta una vez&quot;">​</a></h2><p>Un envío de <code>ctx</code> (en un handler, un flujo o una conversación) que el transporte rechaza con un <code>RateLimitedError</code> que pide esperar como mucho 5 s se reintenta en el sitio. Las alphas reintentaban dos veces; 2.0 reintenta una vez por defecto y permite configurarlo:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Bot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ provider, rateLimitRetry: { retries: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, maxWaitMs: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;10s&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } })</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Bot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ provider, rateLimitRetry: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// nunca reintentar en el sitio</span></span></code></pre></div><p><code>bot.send()</code> no se reintenta (las difusiones y el outbox durable tienen su propio back-off).</p><h2 id="eventos-de-provider-invalidos" tabindex="-1">Eventos de provider inválidos <a class="header-anchor" href="#eventos-de-provider-invalidos" aria-label="Permalink to &quot;Eventos de provider inválidos&quot;">​</a></h2><p>Un evento que rompe el contrato normalizado (no es un objeto, un <code>kind</code> que no es string, un mensaje sin <code>chatId</code>, <code>ref</code>, <code>senderId</code>, <code>type</code> o <code>body</code>…) fallaba dentro del pipeline con un <code>TypeError</code> genérico. Ahora se descarta y se informa una sola vez en el evento <code>&#39;error&#39;</code> como <code>InvalidProviderEventError</code>, que nombra el provider y el campo roto (nunca ids ni contenido de mensajes). Un evento cuyo <code>kind</code> es un string que este core no conoce (un provider más nuevo) no es un error: se ignora, con una línea de log en debug, para que los providers puedan añadir tipos de evento sin romper cores anteriores.</p><h2 id="un-hook-que-llama-a-next-dos-veces" tabindex="-1">Un hook que llama a <code>next()</code> dos veces <a class="header-anchor" href="#un-hook-que-llama-a-next-dos-veces" aria-label="Permalink to &quot;Un hook que llama a `next()` dos veces&quot;">​</a></h2><p>Un hook <code>before</code> que llamaba a <code>next()</code> dos veces lanzaba <code>next() called multiple times</code> y el mensaje se perdía. Ahora se conserva el primer despacho (el resto de la cadena corre una vez y cada <code>next()</code> posterior devuelve la misma promesa) y el mal uso se informa en el evento <code>&#39;error&#39;</code>.</p><h2 id="los-ids-de-los-logs-van-hasheados" tabindex="-1">Los ids de los logs van hasheados <a class="header-anchor" href="#los-ids-de-los-logs-van-hasheados" aria-label="Permalink to &quot;Los ids de los logs van hasheados&quot;">​</a></h2><p>Las líneas de log del propio bot (descartes por listas de acceso y handoff, &quot;dispatching message&quot;, fallos del indicador de escritura, claves de conversación) llevaban los ids de chat y de remitente tal cual: teléfonos o correos. Ahora pasan por una política de ids, <code>BotConfig.logIds</code>:</p><ul><li><code>&#39;hash&#39;</code> (por defecto): HMAC-SHA256 de 16 caracteres, estable dentro del proceso. Con trazas activas es el mismo hash que el de los spans (se reutiliza <code>telemetry.idKey</code>).</li><li><code>&#39;raw&#39;</code>: los ids tal cual, para depurar en local.</li><li><code>&#39;omit&#39;</code>: sin ids.</li></ul><h2 id="logs-append-danados" tabindex="-1">Logs append dañados <a class="header-anchor" href="#logs-append-danados" aria-label="Permalink to &quot;Logs append dañados&quot;">​</a></h2><p>Con <code>appendLog</code>, una línea mala al <strong>final</strong> de <code>&lt;archivo&gt;.log</code> es una escritura cortada y se recorta, como antes. Una línea mala en <strong>medio</strong> se trataba igual, y se perdían en silencio todas las entradas posteriores. <code>FileDurability.open()</code> y <code>SharedFileEventJournal.open()</code> rechazan ahora ese log con un error de <code>code</code><code>&#39;APPEND_LOG_CORRUPT&#39;</code> (indica el archivo, la línea y el byte) y no lo tocan: restáuralo desde una copia o córtalo en esa línea.</p><p>Los snapshots pueden forzarse a disco antes de reemplazar al anterior: <code>FileDurability.open(ruta, { fsync: true })</code>, y la misma opción <code>fsync</code> en <code>FileEventJournal</code> y <code>SharedFileEventJournal</code>.</p><h2 id="memorycoordinationhub-expulsa-chats-inactivos" tabindex="-1"><code>MemoryCoordinationHub</code> expulsa chats inactivos <a class="header-anchor" href="#memorycoordinationhub-expulsa-chats-inactivos" aria-label="Permalink to &quot;`MemoryCoordinationHub` expulsa chats inactivos&quot;">​</a></h2><p>El hub de coordinación en proceso guardaba el estado de cada chat para siempre. Ahora expulsa los chats inactivos por encima de <code>maxIdleKeys</code> (por defecto 10.000; <code>Infinity</code> los conserva todos). Los fences siguen siendo monótonos tras una expulsión; un chat recreado informa <code>previousHolder: null</code>, así que su siguiente titular refresca su estado. El chat que se está usando nunca se expulsa, así que <code>maxIdleKeys: 0</code> conserva solo el último chat inactivo.</p><h2 id="reintentos-de-broadcast" tabindex="-1">Reintentos de <code>broadcast</code> <a class="header-anchor" href="#reintentos-de-broadcast" aria-label="Permalink to &quot;Reintentos de `broadcast` {#reintentos-de-broadcast}&quot;">​</a></h2><p><code>bot.broadcast(ids, contenido, { maxRetries })</code> pasa a ser <code>{ retries }</code>, con el mismo significado (reintentos después del primer envío de cada chat). <code>maxRetries</code> sigue funcionando y queda obsoleto. <code>autoReconnect.maxRetries</code> del manager se renombra igual.</p><h2 id="las-etiquetas-de-whatsapp-flows-pasan-a-ingles" tabindex="-1">Las etiquetas de WhatsApp Flows pasan a inglés <a class="header-anchor" href="#las-etiquetas-de-whatsapp-flows-pasan-a-ingles" aria-label="Permalink to &quot;Las etiquetas de WhatsApp Flows pasan a inglés&quot;">​</a></h2><p><code>@botmesh/meta</code> construye el WhatsApp Flow nativo de un formulario con <code>toFlowJson()</code> y <code>provider.publishForm()</code>. La etiqueta del botón de envío queda fijada en el Flow publicado, y su valor por defecto seguía en español (<code>&#39;Enviar&#39;</code>) mientras el core pasaba a inglés. Ahora usa el locale por defecto del core: <code>&#39;Submit&#39;</code>. Los textos de reserva que se usan al enviar una definición sin contexto de bot (<code>&#39;Open form&#39;</code>, <code>&#39;Fill in the form.&#39;</code>) también. Para conservar las etiquetas en español:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toFlowJson</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(definicion, { lang: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;es&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> CloudAPIProvider</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">config, lang: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;es&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// todos los publishForm() de este provider</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">provider.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">publishForm</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(definicion, { lang: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;es&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// o un Flow</span></span></code></pre></div><p>El <code>lang</code> del provider es el idioma de tu bot (<code>BotConfig.lang</code>): un bot con <code>lang: &#39;es&#39;</code> pone el mismo valor en su <code>CloudAPIProvider</code>. Un <code>submitLabel</code> en la definición siempre manda. Los formularios que envía un bot ya usan el <code>ctx.lang</code> del usuario para el botón y el cuerpo.</p><h2 id="presencia-sin-conexion" tabindex="-1">Presencia sin conexión <a class="header-anchor" href="#presencia-sin-conexion" aria-label="Permalink to &quot;Presencia sin conexión&quot;">​</a></h2><p><code>ctx.typing()</code>, <code>ctx.recording()</code>, <code>ctx.markRead()</code> y el indicador automático de escritura son señales de mejor esfuerzo. Antes se comportaban distinto en cada canal mientras el transporte estaba caído: Baileys no hacía nada, los canales REST llamaban igual a la API y algunos rechazaban. Ahora hay una sola regla (la sección &quot;PRESENCE WHILE DISCONNECTED&quot; del contrato <code>IProvider</code>): mientras el último estado de conexión del provider no es <code>&#39;ready&#39;</code>, o una vez parado el bot, la señal se omite sin error, se registra en debug y se cuenta en <code>metrics().presenceSkipped</code> (<code>botmesh_presence_skipped_total</code> en <code>toPrometheus()</code>). Los 13 providers integrados la cumplen también si se les llama directamente. Ya conectado, un fallo del transporte sigue rechazando como antes.</p><p>Un provider propio debe resolver <code>typing()</code> y <code>markRead()</code> sin tocar su transporte mientras no está conectado; <code>assertPresenceWhileDisconnected()</code> de <code>@botmesh/core/testing</code> lo comprueba. Un provider que nunca emite un evento de conexión no queda limitado por el bot mientras este corre.</p><h2 id="evento-stopping" tabindex="-1">Evento <code>&#39;stopping&#39;</code> <a class="header-anchor" href="#evento-stopping" aria-label="Permalink to &quot;Evento `&#39;stopping&#39;` {#evento-stopping}&quot;">​</a></h2><p><code>bot.stop()</code> sobre un bot en marcha emite ahora <code>&#39;stopping&#39;</code> justo después de cerrar la entrada, antes del drenado y antes de parar el transporte; <code>&#39;stopped&#39;</code> sigue llegando al final. Cancela ahí el trabajo largo (llamadas al modelo, descargas): el transporte todavía puede entregar lo que está en curso. <code>@botmesh/ai</code> aborta sus llamadas al modelo en <code>&#39;stopping&#39;</code> (antes esperaba a <code>&#39;stopped&#39;</code>, con el transporte ya parado).</p><h2 id="los-flujos-persistentes-hacen-checkpoint-al-empezar" tabindex="-1">Los flujos persistentes hacen checkpoint al empezar <a class="header-anchor" href="#los-flujos-persistentes-hacen-checkpoint-al-empezar" aria-label="Permalink to &quot;Los flujos persistentes hacen checkpoint al empezar&quot;">​</a></h2><p>Un flujo <code>.persistent()</code> escribe ahora su checkpoint al empezar (paso 0) además de después de cada paso, así que un reinicio mientras espera su primer paso, normalmente un flujo que empieza con <code>.ask()</code>, lo retoma ahí y vuelve a preguntar. Antes se perdía salvo con durabilidad o coordinación. El coste es una escritura de checkpoint más por entrada al flujo.</p><h2 id="mensajes-de-error-sin-ids-de-chat" tabindex="-1">Mensajes de error sin ids de chat <a class="header-anchor" href="#mensajes-de-error-sin-ids-de-chat" aria-label="Permalink to &quot;Mensajes de error sin ids de chat&quot;">​</a></h2><p>Los mensajes por defecto de <code>OutsideSessionWindowError</code> y <code>RecipientUnreachableError</code> ya no incluyen el id del chat (acababa en los logs): dicen <code>Outside the session window; a template is required</code> y <code>Recipient unreachable</code>. El id sigue en <code>error.chatId</code>, y un mensaje que pase el provider se conserva tal cual.</p><h2 id="arreglos-menores" tabindex="-1">Arreglos menores <a class="header-anchor" href="#arreglos-menores" aria-label="Permalink to &quot;Arreglos menores&quot;">​</a></h2><ul><li><code>ctx.delete()</code> antes de <code>start()</code> o después de <code>stop()</code> rechaza con <code>BotNotRunningError</code> (<code>operation: &#39;delete&#39;</code>), como los envíos.</li><li><code>IMessageContext.acknowledge</code> se tipa como método obligatorio: siempre existió en ejecución (sin interacción no hace nada). <code>ctx.acknowledge?.()</code> sigue compilando.</li><li>Un evento de provider cuyo <code>kind</code> es un string que el core no conoce se ignora con una línea en debug en vez de informarse como <code>InvalidProviderEventError</code>.</li><li><code>lang</code> e <code>i18n.defaultLocale</code> pueden nombrar el mismo idioma con distinta precisión (<code>&#39;es&#39;</code> y <code>&#39;es-MX&#39;</code>); la etiqueta más específica queda como predeterminada.</li><li>Con <code>telemetry.ids: &#39;raw&#39;</code> y sin <code>logIds</code>, las líneas de log siguen hasheando los ids (antes reutilizaban la política cruda de los spans).</li><li><code>ChaosProvider.selfId</code> y <code>RecordingProvider.selfId</code> (<code>@botmesh/core/testing</code>) devuelven <code>null</code> en vez de <code>undefined</code> cuando el provider envuelto no tiene id propio, así implementan <code>IProvider</code> con <code>exactOptionalPropertyTypes</code>.</li><li>En el outbox durable, una parte posterior de un texto dividido ya no adelanta a una anterior que espera un reintento, y el barrido divide un registro anotado que supera el límite de texto del canal (ver <a href="/botmesh/es/guide/durabilidad">Procesamiento durable</a>). Esperar detrás de una parte anterior no gasta intentos, y las partes se enlazan con el nuevo campo <code>OutboxRecord.previousPart</code> (tus propias claves de idempotencia que acaban en <code>#&lt;n&gt;</code> no se tratan como partes). Un <code>OutboxJournal</code> propio debe guardar <code>previousPart</code> en <code>put()</code> y respetar la nueva opción <code>markFailed(..., { refund: true })</code> (devolver el intento reclamado); si las ignora, las partes siguen sin orden en los reintentos, como antes.</li></ul><h2 id="siguientes-pasos" tabindex="-1">Siguientes pasos <a class="header-anchor" href="#siguientes-pasos" aria-label="Permalink to &quot;Siguientes pasos&quot;">​</a></h2><ul><li><a href="./actualizar-canales-plugins">Notas de actualización: canales y plugins</a></li><li><a href="./migracion-estable">Actualizar a estable: checklist y cambios de API</a></li></ul>',57)])])}const m=a(t,[["render",n]]);export{u as __pageData,m as default};
